'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { scale } = require('../src/recipescale');

const CASES = [
  [["5/2 pinch black pepper
12 pinch milk
6 cinnamon
", "4:6"], "3 3/4 pinch black pepper
3 dash milk
9 cinnamon
"],
  [["39 oats
1/3 spoon lemon juice
2 1/8 milk
11 barley", "2:5"], "98 oats
3 3/8 dash lemon juice
5 milk
28 barley"],
  [["# soup for the quay
4 2/4 egg
21 spoon sea salt
5/8 spoon stock
", "6:3"], "# soup for the quay
2 egg
10 1/2 spoon sea salt
1 1/4 dash stock
"],
];

CASES.forEach(([args, want], i) => {
  test(`case ${i}: ${JSON.stringify(args)}`, () => {
    assert.strictEqual(scale(...args), want);
  });
});

